<?php declare(strict_types=1);
$ct=$ivCatalogueText;
$assetFilters=scalarFields($_GET,['category','member','location']);$assets=$inventory->assetsPage($assetFilters,$_GET['asset_page']??1);$assetListRoute=['view'=>'inventory','tab'=>'assets']+$assetFilters;
?>
<section class="card iv-catalogue" id="inventory-assets-catalogue"><div class="section-heading"><div><h2><?= e($ct('Dokumentierte Gegenstandswerte')) ?></h2><p class="muted"><?= e($ct('Nur aktive Gegenstände: Wert je Einheit × Bestand oder der auf die erfassten Teile verteilte Rechnungsbetrag. Archivierte Gegenstände bleiben mit ihren Belegen im Archiv erhalten. Fremde Leihgaben und verknüpfte Handkassen sind ausgenommen.')) ?></p></div><strong class="iv-value-total"><?= euro((int)$assets['total']) ?></strong></div><p><?= e($ct('Diese Inventarwertsumme ist kein Bank- oder Kassenbestand und kein steuerlicher Buchwert. Abschreibungen werden nicht berechnet. {count} eigene Gegenstände haben noch keinen dokumentierten Wert.',['count'=>$assets['unvalued']])) ?></p>
<form method="get" class="iv-filter"><?= hidden('view','inventory').hidden('tab','assets') ?><?php ivField('category',$ct('Kategorie'),input($_GET,'category'));if($ivRead){ivField('member',$ct('Zuständiges Mitglied'),input($_GET,'member'),'select',\Kulturhus\Verein\Web\InventoryCatalogueForm::options(array_replace($personOptions,[''=>$ct('Alle Personen')]),input($_GET,'member'),$ct('Ausgewählte Person nicht verfügbar – Filter prüfen')));ivField('location',$ct('Aktueller Lagerort'),input($_GET,'location'),'select',\Kulturhus\Verein\Web\InventoryCatalogueForm::options(array_replace($locationOptions,[''=>$ct('Alle Lagerorte')]),input($_GET,'location'),$ct('Ausgewählter Lagerort nicht verfügbar – Filter prüfen')));} ?><button class="btn btn-outline theme-secondary secondary"><?= e($ct('Filtern')) ?></button></form><p class="muted"><?= e($ct('Die Ortsauswahl zeigt Gegenstände mit Bestand am gewählten Ort; die Wertspalte bezieht sich auf den gesamten Gegenstand über alle Orte.')) ?></p>
<link rel="stylesheet" href="inventory-catalogue.css?v=2">
<p data-inventory-assets-summary><?= e($ct('{count} Gegenstände · Seite {page} von {pages}',['count'=>$assets['count'],'page'=>$assets['page'],'pages'=>$assets['pages']])) ?></p>
<div class="iv-catalogue-cards"><?php foreach($assets['rows']as$r): ?><article class="iv-catalogue-card" data-inventory-asset="<?= e($r['id']) ?>">
<?php if($ivRead): ?><a class="btn btn-outline theme-secondary" href="<?= e(url(array_replace($assetListRoute,['asset_page'=>$assets['page'],'return_assets'=>1,'item'=>$r['id'],'tab'=>'items']))) ?>"><?= e($r['name']) ?></a><?php else: ?><strong><?= e($r['name']) ?></strong><?php endif ?>
<p><?= e($r['code'].' · '.$r['category']) ?></p><p><?= e($ct($r['ownership']==='club'?'Vereinseigentum':'Fremde Leihgabe')) ?> · <?= e($r['responsible_name']??'') ?></p>
<dl><div><dt><?= e($ct('Gesamtmenge')) ?></dt><dd><?= e(\Kulturhus\Verein\Inventory::contentSummary($r,(int)$r['quantity'],$ct)?:$r['quantity'].' '.$r['unit']) ?></dd></div>
<div><dt><?= e($ct('Dokumentierter Stückwert')) ?></dt><dd><?php if(isset($r['allocated_unit_min_cents'])): ?><?= (int)$r['allocated_unit_min_cents']===(int)$r['allocated_unit_max_cents']?euro((int)$r['allocated_unit_min_cents']):euro((int)$r['allocated_unit_min_cents']).'–'.euro((int)$r['allocated_unit_max_cents']) ?><?php elseif(!empty($r['has_purchase_units'])): ?><?= e($ct('Je Stück erfasst')) ?><?php elseif($r['unit_value_cents']===null): ?><?= e($ct('Nicht bewertet')) ?><?php else: ?><?= euro((int)$r['unit_value_cents']) ?><?php endif ?></dd></div>
<div><dt><?= e($ct('Wert im Vereinsvermögen')) ?></dt><dd><?= $r['documented_total']===null?e($ct('Nicht enthalten')):euro((int)$r['documented_total']) ?></dd></div></dl></article>
<?php endforeach;if(!$assets['rows']): ?><p><?= e($ct('Keine Gegenstände gefunden.')) ?></p><?php endif ?></div>
<nav class="iv-catalogue-pages" aria-label="<?= e($ct('Vermögensseiten')) ?>"><?php foreach([-1=>'Vorherige',1=>'Nächste']as$delta=>$label)if($assets['page']+$delta>=1&&$assets['page']+$delta<=$assets['pages']): ?><a class="btn btn-outline theme-secondary" href="<?= e(url($assetListRoute+['asset_page'=>$assets['page']+$delta])) ?>"><?= e($ct($label)) ?></a><?php endif ?></nav>
<form method="get" class="iv-catalogue-pages"><?php foreach($assetListRoute as$key=>$value)echo hidden($key,$value); ?><label><?= e($ct('Seite')) ?><input class="form-control" type="number" name="asset_page" min="1" max="<?= (int)$assets['pages'] ?>" value="<?= (int)$assets['page'] ?>" required></label><button class="btn btn-outline theme-secondary"><?= e($ct('Seite anzeigen')) ?></button></form>
</section>
